import {materialPack} from './material-pack.js';
import {getBuildingFinish,setBuildingFinish,previewBuildingFinish,showMaterialCoupon,selectMaterialCouponZone} from './grammar-review.js';
import {BUILDING_ZONES,BUILDING_PROFILES,BUILDING_FINISH_KEY,buildingMaterialRecipe,buildingMaterialPreset,buildingZone} from './building-material.js';
const $=id=>document.getElementById(id),host=$('materialDesigner');let recipe=getBuildingFinish(),active=0,tiles,tab='finish',timer,localEdits=false;
const field=(id,label,min=0,max=1,step=.01)=>`<label for="mat-${id}">${label}<output id="mat-${id}-value"></output></label><input id="mat-${id}" data-field="${id}" type="range" min="${min}" max="${max}" step="${step}">`;
host.innerHTML=`<label for="mat-preset">Start from a building history</label><select id="mat-preset"><option value="custom" selected>Current / custom recipe</option><option value="inhabited">Inhabited / lightly weathered</option><option value="new">Newly commissioned</option><option value="industrial">Industrial / maintenance overdue</option><option value="desert">Arid / windborne dust</option><option value="coastal">Coastal / salt and rain</option></select><label for="mat-zone">Building material zone</label><select id="mat-zone">${BUILDING_ZONES.map((n,i)=>`<option value="${i}">${String(i+1).padStart(2,'0')} / ${n}</option>`).join('')}</select><div class="material-tabs" role="tablist" aria-label="Material controls">${[['finish','Finish'],['weather','Weathering'],['inspect','Inspect / save']].map(([id,name])=>`<button id="mat-tab-${id}" role="tab" aria-controls="mat-panel-${id}" aria-selected="${id==='finish'}">${name}</button>`).join('')}</div>
<div id="mat-panel-finish" class="material-panel" role="tabpanel"><label for="mat-profile">Surface construction</label><select id="mat-profile">${Object.entries(BUILDING_PROFILES).map(([id,p])=>`<option value="${id}">${p.label}</option>`).join('')}</select><label for="mat-color">Coating / material color</label><input id="mat-color" type="color">${field('roughness','Surface roughness',.16,.96)}${field('grain','Microstructure / grain')}${field('relief','Height relief',0,2,.05)}<div class="row"><div>${field('panelsX','Joints across / 2 m',1,4,1)}</div><div>${field('panelsY','Joints vertically / 2 m',1,4,1)}</div></div><p class="material-note">Coating and substrate have distinct responses. Chips expose the substrate; grime and oxide reduce exposed metal reflectance.</p></div>
<div id="mat-panel-weather" class="material-panel" role="tabpanel" hidden><div class="layer-heading">This material zone</div>${field('wear','Service age / coating loss')}${field('chips','Edge chipping')}${field('grime','Joint grime')}${field('streaks','Runoff streaks')}${field('oxidation','Oxide / corrosion')}${field('deposits','Mineral / dust deposits')}<div class="layer-heading">Whole building exposure</div>${field('rain','Rain exposure')}${field('dust','Airborne dust')}${field('wetness','Patchy surface wetness')}${field('biology','Low-level biological film')}<p class="material-note">Gravity-aligned streaks and ground accumulation are evaluated over the building in metres. Aluminum receives pale oxidation; orange corrosion belongs to exposed steel.</p></div>
<div id="mat-panel-inspect" class="material-panel" role="tabpanel" hidden><label for="mat-seed">Material seed</label><input id="mat-seed"><label for="mat-resolution">Finish tile resolution</label><select id="mat-resolution"><option value="512">512² / fast iteration</option><option value="1024">1024² / fine inspection</option></select><label for="mat-channel">Building inspection channel</label><select id="mat-channel"><option value="0">Lit material</option><option value="1">Base color</option><option value="2">Tangent-space normal</option><option value="3">Roughness</option><option value="4">Metalness</option><option value="5">Height / contrast enhanced</option><option value="6">Cavity occlusion</option></select><div id="mat-maps" class="map-grid"></div><p id="mat-metrics" class="material-note"></p><div class="row"><button id="mat-export">Export recipe</button><button id="mat-import">Import recipe</button></div><button id="mat-png">Export material pack (.zip)</button><input id="mat-file" type="file" accept="application/json,.json" hidden><p class="material-note">Map exports: sRGB base color, linear normal, packed AO / roughness / metalness / height, and coating loss / grime / runoff / deposits. Height = (alpha / 255 − 0.5) / 40 metres.</p></div>
<div id="mat-state" class="material-state" role="status">Synthesizing eight finish zones…</div><button id="mat-bake" class="primary">Bake material layers</button><button id="mat-save">Use finish in Native Building Lab</button><button id="mat-reset">Reset this material zone</button><p class="material-note">Procedural maps and physical lighting. No photographs or downloaded material packs.</p>`;
function state(text){$('mat-state').textContent=text;}
function refresh(){const z=recipe.zones[active];for(const input of host.querySelectorAll('[data-field]')){const k=input.dataset.field,v=k in recipe.weather?recipe.weather[k]:z[k];input.value=v;$('mat-'+k+'-value').textContent=['panelsX','panelsY'].includes(k)?v:k==='relief'?v.toFixed(2)+'×':Math.round(v*100)+'%';}$('mat-profile').value=z.profile;$('mat-color').value=z.color;$('mat-seed').value=recipe.seed;$('mat-resolution').value=recipe.resolution;drawMaps();}
function bake(){clearTimeout(timer);state('Synthesizing eight finish zones…');setBuildingFinish(recipe);}
function changed(){localEdits=true;$('mat-preset').value='custom';state('Changed · preparing material layers');clearTimeout(timer);timer=setTimeout(bake,350);}
for(const input of host.querySelectorAll('[data-field]')){input.oninput=()=>{const k=input.dataset.field,v=Number(input.value);if(k in recipe.weather)recipe.weather[k]=v;else recipe.zones[active][k]=v;$(input.id+'-value').textContent=['panelsX','panelsY'].includes(k)?v:k==='relief'?v.toFixed(2)+'×':Math.round(v*100)+'%';};input.onchange=changed;}
for(const id of ['finish','weather','inspect'])$('mat-tab-'+id).onclick=()=>{tab=id;for(const t of ['finish','weather','inspect']){$('mat-panel-'+t).hidden=t!==tab;$('mat-tab-'+t).setAttribute('aria-selected',String(t===tab));}};
$('mat-zone').onchange=()=>{active=Number($('mat-zone').value);selectMaterialCouponZone(active);refresh();};$('mat-profile').onchange=()=>{recipe.zones[active]=buildingZone($('mat-profile').value);refresh();changed();};$('mat-color').oninput=()=>recipe.zones[active].color=$('mat-color').value;$('mat-color').onchange=changed;
$('mat-preset').onchange=()=>{if($('mat-preset').value==='custom')return;recipe=buildingMaterialPreset($('mat-preset').value,recipe.seed);recipe.resolution=Number($('mat-resolution').value);refresh();localEdits=true;bake();};$('mat-seed').onchange=()=>{recipe.seed=$('mat-seed').value;changed();};$('mat-resolution').onchange=()=>{recipe.resolution=Number($('mat-resolution').value);changed();};$('mat-channel').onchange=()=>previewBuildingFinish($('mat-channel').value);
$('mat-bake').onclick=bake;$('mat-reset').onclick=()=>{recipe.zones[active]=buildingMaterialRecipe().zones[active];refresh();changed();};
$('mat-save').onclick=()=>{try{localStorage.setItem(BUILDING_FINISH_KEY,JSON.stringify(buildingMaterialRecipe(recipe)));state('Saved · open the Native Building Lab to use this finish');}catch(e){state('Could not save: '+e.message);}};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('mat-export').onclick=()=>download(new Blob([JSON.stringify(buildingMaterialRecipe(recipe),null,2)],{type:'application/json'}),'aether-building-material.json');$('mat-import').onclick=()=>$('mat-file').click();$('mat-file').onchange=async()=>{try{const value=JSON.parse(await $('mat-file').files[0].text());if(value.schema!=='aether.building-material/1')throw Error('Choose an Aether building material recipe');recipe=buildingMaterialRecipe(value);$('mat-preset').value='custom';refresh();bake();}catch(e){state('Import failed: '+e.message);}finally{$('mat-file').value='';}};
function mapCanvas(t,key,opaque=false){const canvas=document.createElement('canvas');canvas.width=canvas.height=t.size;canvas.getContext('2d').putImageData(new ImageData((()=>{const data=new Uint8ClampedArray(t[key]);if(opaque)for(let i=3;i<data.length;i+=4)data[i]=255;return data;})(),t.size,t.size),0,0);return canvas;}
function drawMaps(){if(!tiles)return;const t=tiles[active],grid=$('mat-maps');grid.replaceChildren();for(const [name,key,channel]of [['Base color','color',1],['Normal','normal',2],['Packed surface','surface',3],['Layer masks','masks',0]]){const b=document.createElement('button');b.title='Inspect '+name;b.append(mapCanvas(t,key,true));const label=document.createElement('span');label.textContent=name;b.append(label);b.onclick=()=>{$('mat-channel').value=String(channel);previewBuildingFinish(channel);};grid.append(b);}$('mat-metrics').textContent=`${t.size}² tile · ${t.stats.texelsPerMeter} texels/metre · height ${(t.stats.minHeight*1000).toFixed(2)} to ${(t.stats.maxHeight*1000).toFixed(2)} mm. All zones share three atlased texture maps.`;}
function scalarMap(t,channel){const data=new Uint8ClampedArray(t.surface.length);for(let i=0;i<data.length;i+=4)data.set([t.surface[i+channel],t.surface[i+channel],t.surface[i+channel],255],i);const canvas=document.createElement('canvas');canvas.width=canvas.height=t.size;canvas.getContext('2d').putImageData(new ImageData(data,t.size,t.size),0,0);return canvas;}
$('mat-png').onclick=async()=>{if(!tiles||document.body.dataset.baking==='true'){state('Wait for the material bake to finish');return;}const index=active,t=tiles[index],snapshot=buildingMaterialRecipe(recipe);state('Packing selected material zone…');try{const entries=[];for(const [name,canvas]of [...['color','normal','surface','masks'].map(k=>[k,mapCanvas(t,k)]),...['ao','roughness','metalness','height'].map((k,i)=>[k,scalarMap(t,i)])]){const blob=await new Promise(resolve=>canvas.toBlob(resolve));if(!blob)throw Error('PNG encoding failed');entries.push({name:name+'.png',blob});}entries.push({name:'recipe.json',blob:new Blob([JSON.stringify(snapshot,null,2)])},{name:'README.txt',blob:new Blob([`Aether procedural building material / zone ${index+1}\n2 metres per repeat. Base color is sRGB; all other maps are linear data.\nHeight metres = (height.png red / 255 - 0.5) / 40. Surface RGBA = AO, roughness, metalness, height.\nMasks RGBA = coating loss, grime, runoff, deposits. PNG alpha in packed maps is data, not opacity.\nThe exported tiles contain periodic detail layers. World-space exposure is evaluated by the native shader using recipe.weather.\nNormal map: tangent space, positive green is positive texture V.\n`])});download(await materialPack(entries),`aether-building-zone-${index+1}.zip`);state('Material pack exported');}catch(e){state('Export failed: '+e.message);}};

window.addEventListener('aether:finish-progress',e=>state('Synthesizing material layers · '+Math.round(e.detail*100)+'%'));window.addEventListener('aether:finish-error',e=>state('Material error: '+e.detail));window.addEventListener('aether:finish-baked',e=>{tiles=e.detail.tiles;if(!localEdits){recipe=e.detail.recipe;refresh();}drawMaps();state('Ready · all eight material zones baked');document.body.dataset.materialReady='true';});
window.addEventListener('pagehide',()=>clearTimeout(timer),{once:true});refresh();

for(const [id,target]of [['fit','fit'],['detail','detail'],['entry','entry']])$('mat-camera-'+id).onclick=() => $(target).click();

$('mat-camera-coupon').onclick=()=>showMaterialCoupon(active);
